import{_ as t,o as l,c as o,a3 as r}from"./chunks/framework.Dj4Lt7vj.js";const g=JSON.parse('{"title":"查询表与登记表","description":"","frontmatter":{"title":"查询表与登记表"},"headers":[],"relativePath":"solution/tables.md","filePath":"solution/tables.md","lastUpdated":1787949005000}'),e={name:"solution/tables.md"};function i(s,a,n,c,d,h){return l(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="查询表与登记表" tabindex="-1">查询表与登记表 <a class="header-anchor" href="#查询表与登记表" aria-label="Permalink to &quot;查询表与登记表&quot;">​</a></h1><p>表格让 AI 能「查数据」和「记事情」：</p><ul><li><strong>查询表</strong>：AI 检索用的结构化数据。比如库存价格表、快递时效表——顾客问「加大码还有货吗」，AI 从表里查了再答。</li><li><strong>登记表</strong>：AI 记录顾客需求用的表。比如售后登记、到货提醒登记——顾客说「到货叫我」，AI 把顾客和诉求写进表里，提醒你跟进。</li></ul><p>入口：客户端左侧菜单「表格」，或网页工作台「表格」标签页。</p><div class="warning custom-block"><p class="custom-block-title">按套餐开放</p><p>表格按套餐开放。当前套餐未包含时请联系销售开通，具体以「账单」页为准，见<a href="/aicare-docs/start/plan">套餐与开通</a>。</p></div><h2 id="创建查询表" tabindex="-1">创建查询表 <a class="header-anchor" href="#创建查询表" aria-label="Permalink to &quot;创建查询表&quot;">​</a></h2><ol><li>在「表格」页新建表，类型选<strong>查询表</strong>。</li><li>定义列：比如「商品名、规格、库存、价格」。</li><li>录入数据，或用 <strong>Excel 导入</strong>批量灌入。</li><li>到方案编辑器的「表格」模块，把表绑定到方案。</li><li>确认 AI 设置里开启了「查询表格」工具，见 <a href="/aicare-docs/solution/agents#工具">AI 设置</a>。</li></ol><p>之后顾客问到表里有的数据，AI 会先查表再回答。</p><h2 id="创建登记表" tabindex="-1">创建登记表 <a class="header-anchor" href="#创建登记表" aria-label="Permalink to &quot;创建登记表&quot;">​</a></h2><ol><li>新建表，类型选<strong>登记表</strong>。</li><li>定义要收集的字段：比如「顾客昵称、商品、问题描述、联系方式」。</li><li>绑定到方案，并确认 AI 设置里开启了「登记记录」工具。</li></ol><p>顾客提出需要跟进的诉求时，AI 会引导顾客补全信息并写入登记表。你在「表格」页查看新登记的条目，支持 <strong>Excel 导出</strong>。</p><h2 id="使用建议" tabindex="-1">使用建议 <a class="header-anchor" href="#使用建议" aria-label="Permalink to &quot;使用建议&quot;">​</a></h2><ul><li><strong>列名写通俗</strong>。AI 靠列名理解数据含义，「库存数量」比「qty」好。</li><li><strong>数据保持最新</strong>。查询表答出旧库存比不答更伤顾客信任；大促前记得更新。</li><li><strong>登记表定期清</strong>。处理完的条目及时标记或导出归档，别让表变成没人看的黑洞。</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>查询表和知识库有什么区别？</strong> 查询表适合行列结构的数据（几百个 SKU 的库存价格），精确匹配查询；知识库适合成段的说明文字（政策、说明），语义检索。两者互补。</p><p><strong>登记之后会提醒我吗？</strong> 登记条目会出现在表格页。请定期查看；绑定微信后，部分提醒也可以通过微信服务号推送。</p>',16)])])}const u=t(e,[["render",i]]);export{g as __pageData,u as default};
